insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.generic.reasons[0].cites[0].quote', 'Аллах сказал: «Любое деяние сына Адама — для него, кроме поста. Поистине, он — для Меня, и Я воздам за него».');
