insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.ics-title', 'Обязательный (ваджиб) пост');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[1].quote', 'Тому, кто постился в рамадане с верой и надеждой на награду, простятся его прежние грехи.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[1].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[1].hadith', '760');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].hadith', '38');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[0].quote', 'Ислам утверждается на пяти [столпах]: свидетельстве о том, что нет божества, достойного поклонения, кроме Аллаха, и что Мухаммад — Посланник Аллаха; совершении молитвы; выплате закята; совершении хаджа и посте в рамадане.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[0].references[1].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.obligatory.reasons[0].cites[0].references[1].hadith', '16');
