insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].quote', 'Дни ташрика — дни еды и питья.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].references[0].hadith', '1141a');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[1].id', 'fasting-reason-tashriq');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[1].title', 'Дни ташрика');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Абу Убайд (да будет доволен им Аллах) передал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Я присутствовал на праздничной молитве вместе с Умаром. Он начал с молитвы перед проповедью, а затем сказал: «Посланник Аллаха, да благословит его Аллах и приветствует, запретил пост в эти два дня. Что касается дня жертвоприношения, то вы едите мясо ваших жертвенных животных, а что касается дня разговения, то вы прекращаете ваш пост».');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].hadith', '1722');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[0].hadith', '2416');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].intro', 'Абу Хурайра (да будет доволен им Аллах) передал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'Посланник Аллаха, да благословит его Аллах и приветствует, запретил пост в два дня: в день жертвоприношения и в день разговения.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[1].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[1].hadith', '1138');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[0].hadith', '1993');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].headlines.eid-al-adha', 'Ид аль-Адха');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].headlines.eid-al-fitr', 'Ид аль-Фитр');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].id', 'fasting-reason-eid-days');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.reasons[0].title', 'Ид аль-Фитр и Ид аль-Адха');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.prohibiting.title', 'Запрещённый');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.ics-title', 'Добровольный (татавву) пост');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Абу Катада (да будет доволен им Аллах) передал, что Посланник Аллаха, да благословит его Аллах и приветствует, сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Пост в день Арафа — я надеюсь, что Аллах сделает его искуплением грехов за прошедший и будущий год, а пост в день Ашура — искуплением грехов за прошедший год.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].headlines.arafah', 'День Арафа');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].headlines.ashura', 'День Ашура');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].id', 'fasting-reason-arafah-or-ashura');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[1].title', 'День Арафа и день Ашура');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Одна из жён Пророка (да будет доволен ею Аллах) сказала:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Посланник Аллаха, да благословит его Аллах и приветствует, обычно постился в первые девять дней зуль-хиджи, в день Ашура и три дня каждого месяца.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].hadith', '2437');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].id', 'fasting-reason-first-9-dhu-al-hijjah');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[2].title', 'Первые девять дней зуль-хиджи');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Абдуллах ибн Амр ибн аль-Ас (да будет доволен им Аллах) передал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Достаточно тебе поститься три дня каждый месяц, ибо за доброе дело воздаётся десятикратно, и это будет подобно посту в течение всего года.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Абу Катада (да будет доволен им Аллах) передал, что Посланник Аллаха, да благословит его Аллах и приветствует, сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Пост трёх дней каждого месяца и пост в рамадане каждый год — это постоянный пост.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Посланник Аллаха, да благословит его Аллах и приветствует, сказал Абу Зарру:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Тот, кто постится три дня каждый месяц, подобен постящемуся всю жизнь.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'Джарир ибн Абдуллах (да будет доволен им Аллах) передал, что Пророк, да благословит его Аллах и приветствует, сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Пост трёх дней каждого месяца — пост длиной в жизнь; это белые дни: утро тринадцатого, четырнадцатого и пятнадцатого.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Абу Хурайра (да будет доволен им Аллах) сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Мой близкий друг [Пророк], да благословит его Аллах и приветствует, завещал мне три вещи: поститься три дня каждый месяц, совершать два ракаата молитвы ад-духа и совершать витр перед сном.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Абу ад-Дарда (да будет доволен им Аллах) сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Мой близкий друг [Пророк], да благословит его Аллах и приветствует, наказал мне три вещи, которые я никогда не оставлю: он наказал мне поститься три дня каждый месяц.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Пророк Мухаммад, да благословит его Аллах и приветствует, сказал Абу Зарру (да будет доволен им Аллах):');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Если ты постишься [хотя бы] три дня в месяц, то постись тринадцатого, четырнадцатого и пятнадцатого.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[3].title', 'Белые дни');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Усама ибн Зайд (да будет доволен им Аллах) передал, что Посланник Аллаха, да благословит его Аллах и приветствует, сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Это два дня, в которые деяния представляются Господу миров, и я люблю, чтобы мои деяния представлялись, когда я пощусь.');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Абу Катада аль-Ансари (да будет доволен им Аллах) спросил Пророка, да благословит его Аллах и приветствует, о посте в понедельник, и он сказал:');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Это день, в который я родился и в который я был послан [пророком] — или мне было ниспослано [Откровение].');
insert into i18n_bundles (locale, code, value) values ('ru', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
